# Génère content/reading/stories.json : contes traditionnels japonais (domaine public), réécrits
# en japonais simple (N5 à N1), découpés en chapitres de plus en plus longs. Tous sont ouverts dès le départ.
# Notation des furigana : {漢字|かんじ}.
import json, random, re, sys

OUT = sys.argv[1]

def W(jp, reading, fr, en):
    return {"jp": jp, "reading": reading if reading and reading != jp else None, "fr": fr, "en": en}

def Q(fr, en, choices):
    return {"q": {"fr": fr, "en": en}, "choices": [{"fr": a, "en": b} for a, b in choices]}

def C(slug, title, paragraphs, words, questions):
    return {"slug": slug, "title": {"jp": title[0], "fr": title[1], "en": title[2]},
            "paragraphs": [[{"jp": s[0], "fr": s[1], "en": s[2]} for s in p] for p in paragraphs],
            "words": words, "questions": questions}

stories = []

