# ── Mélange des choix (déterministe) et contrôles ──
rng = random.Random(20261110)
RUBY = re.compile(r"\{([^|{}]+)\|([^|{}]+)\}")
day = 0
for s in stories:
    for c in s["chapters"]:
        day += 1
        for q in c["questions"]:
            right = q["choices"][0]
            rng.shuffle(q["choices"])
            q["answer"] = q["choices"].index(right)
        for p in c["paragraphs"]:
            for sen in p:
                rest = RUBY.sub("", sen["jp"])
                assert "{" not in rest and "}" not in rest and "|" not in rest, sen["jp"]
                assert not re.search(r"[一-龯々]", rest), "kanji sans furigana : " + sen["jp"]
                sen["kana"] = RUBY.sub(lambda m: m.group(2), sen["jp"])
        assert RUBY.sub("", c["title"]["jp"]).count("{") == 0

# Ordre de lecture : du N5 au N1 (les nouveaux contes rejoignent leur niveau)
ORDER = {"N5": 0, "N4": 1, "N3": 2, "N2": 3, "N1": 4}
stories.sort(key=lambda s: ORDER[s["level"]])

data = {
  "contentVersion": "2026.11.21",
  "notice": {"fr": "Contes traditionnels japonais (domaine public), réécrits en japonais simple pour Koto Quest.",
             "en": "Traditional Japanese folk tales (public domain), retold in simple Japanese for Koto Quest."},
  "stories": stories,
}
# Les contes coréens (scripts/ko-reading.py), anglais (scripts/en-reading.py) et chinois (scripts/zh-reading.py), espagnols (scripts/es-reading.py) et allemands (scripts/de-reading.py) sont conservés tels quels.
try:
    old = json.load(open(OUT, encoding="utf-8"))
    data["stories"] += [s for s in old["stories"] if s["level"].startswith(("TOPIK", "HSK", "DELE", "GOETHE")) or s["level"] in ("A1", "A2", "B1", "B2", "C1")]
    if "notices" in old:
        data["notices"] = old["notices"]
except FileNotFoundError:
    pass
from reading_roman import add_roman  # rōmaji et romanisation des phrases
add_roman(data)
json.dump(data, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
n = sum(len(s["chapters"]) for s in stories)
sl = [sum(len(p) for p in c["paragraphs"]) for s in stories for c in s["chapters"]]
print(n, "chapitres ;", "phrases par chapitre :", sl)
